  FT["PH-H8423"] = {"id":"PH-H8423","coverage":"full","language":"en","sourceName":"LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation）","sourceUrl":"https://lawphil.net/statutes/repacts/ra2010/ra_9965_2010.html","fetchedAt":"2026-10-06","articleCount":3,"structureMode":"ARTICLE","title":{"zh":null,"en":"An Act Renaming the Bacaca Road Which Connects J.P. Laurel Street and Carlos P. Garcia Highway That Leads to Davao City International Airport as Francisco S. Dizon Road","orig":"An Act Renaming the Bacaca Road Which Connects J.P. Laurel Street and Carlos P. Garcia Highway That Leads to Davao City International Airport as Francisco S. Dizon Road"},"level":"law","status":"active","topics":["general"],"docNumber":"Republic Act No. 9965","issuingBody":"Congress of the Philippines","promulgatedDate":"2010-01-15","completenessNote":"全文，共 3 条；逐字取自 LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation） 官方页面（statutes/repacts/ra2010/ra_9965_2010.html），未改写、未摘译、未节选；原文语言：英语。 条文抬头依源文为 “Section N.” 等形式，本库统一规范为 “Section N.”；首行抬头与条内标题的分段依源文块级边界还原。","country":"PH","countryName":"菲律宾","layer":"intl","articles":[{"id":"PH-H8423-A1","no":1,"noLabel":{"en":"Section 1."},"text":{"en":"The Bacaca Road which connects J.P. Laurel Street and Carlos P. Garcia Highway that leads to Davao City International Airport shall hereinafter be known as Francisco S. Dizon Road."}},{"id":"PH-H8423-A2","no":2,"noLabel":{"en":"Section 2."},"text":{"en":"The Department of Public Works and Highways shall issue the necessary rules, orders and circulars to implement the provision of this Act."}},{"id":"PH-H8423-A3","no":3,"noLabel":{"en":"Section 3."},"text":{"en":"This Act shall take effect fifteen (15) days after its publication in a newspaper of general circulation."}}],"pack":"ph-p120"};
  FT["PH-H8424"] = {"id":"PH-H8424","coverage":"full","language":"en","sourceName":"LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation）","sourceUrl":"https://lawphil.net/statutes/repacts/ra2010/ra_9966_2010.html","fetchedAt":"2026-10-06","articleCount":29,"structureMode":"ARTICLE","title":{"zh":null,"en":"An Act Converting the Sultan Kudarat Polytechnic State College (Skpsc) in the City of Tacurong and Its Designated Campuses in the Municipalities of Lutayan, Kalamansig, Palimbang and Isulan, All Located in the Province of Sultan Kudarat Into a State University to Be Known as the Sultan Kudarat State University (SKSU) and Appropriating Funds Therefor","orig":"An Act Converting the Sultan Kudarat Polytechnic State College (Skpsc) in the City of Tacurong and Its Designated Campuses in the Municipalities of Lutayan, Kalamansig, Palimbang and Isulan, All Located in the Province of Sultan Kudarat Into a State University to Be Known as the Sultan Kudarat State University (SKSU) and Appropriating Funds Therefor"},"level":"law","status":"active","topics":["education"],"docNumber":"Republic Act No. 9966","issuingBody":"Congress of the Philippines","promulgatedDate":"2010-01-18","completenessNote":"全文，共 29 条；逐字取自 LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation） 官方页面（statutes/repacts/ra2010/ra_9966_2010.html），未改写、未摘译、未节选；原文语言：英语。 条文抬头依源文为 “Section N.” 等形式，本库统一规范为 “Section N.”；首行抬头与条内标题的分段依源文块级边界还原。","country":"PH","countryName":"菲律宾","layer":"intl","articles":[{"id":"PH-H8424-A1","no":1,"noLabel":{"en":"Section 1."},"text":{"en":"Conversion. - The Sultan Kudarat Polytechnic State College (SKPSC) in the City of Tacurong, together with its duly designated campuses in the municipalities of Lutayan, Kalamansig, Palimbang and Isulan, all located in the Province of Sultan Kudarat, is hereby converted into a state university to be known as the Sultan Kudarat State University (SKSU), hereinafter referred to as the University. The main campus of the University shall be in the City of Tacurong."}},{"id":"PH-H8424-A2","no":2,"noLabel":{"en":"Section 2."},"text":{"en":"General Mandate. - The University shall primarily provide advanced instruction and professional training in science and technology, agriculture, fisheries, education and other relevant fields of study. It shall also undertake research and extension services, and provide progressive leadership in its areas of specialization."}},{"id":"PH-H8424-A3","no":3,"noLabel":{"en":"Section 3."},"text":{"en":"Curricular Offerings. - The University shall offer undergraduate and graduate courses in science and technology, agriculture, fisheries, education and other related fields of study within its areas of specialization and according to its capabilities as the Board of Regents may deem necessary to carry out its objectives, in order to meet the needs of the Province of Sultan Kudarat and Region XII: Provided, That no degree program shall be offered without the approval of the Commission on Higher Education (CHED) before the same shall be approved by its Board.\nThe existing high schools shall be transferred to the jurisdiction and supervision of the Department of Education (DepED): Provided, That the high schools, shall be allowed to remain and operated within the campus of the University until the students, who are currently enrolled, shall have completed their high school education: Provided, further, That the University may operate a reasonably-sized laboratory school, if it has a college of Education."}},{"id":"PH-H8424-A4","no":4,"noLabel":{"en":"Section 4."},"text":{"en":"Administration. - The University shall have the general powers of a corporation set forth in Batas Pambansa Blg. 68, as amended, otherwise known as \"The Corporation Code of the Philippines\". The administration of the University and the exercise if its corporate powers shall be vested exclusively in the Board of Regents and the President of the University."}},{"id":"PH-H8424-A5","no":5,"noLabel":{"en":"Section 5."},"text":{"en":"The Governing Board. - The governing board of the University shall be the Board of Regents, hereinafter referred to as the Board, which shall be composed of the following:\n(a)The Chairperson of the Commission on Higher Education (CHED), Chairperson (b)The President of the University, Vice Chairperson;\n(c)The Chairperson of the Committee on Education, Arts and Culture of the Senate, member;\n(d)The Chairperson of the Committee on Higher and Technical Education of the House of Representatives, member;\n(e)The Regional Director of the National Economic and Development Authority (NEDA), member;\n(f)The Regional Director of the Department of Science and Technology (DOST), member;\n(g)The President of the federation of faculty associations of the University, member;\n(h)The President of the federation of student councils of the University, member;\n(i)The President of the federation of alumni associations of the University, member; and (j)Two (2) prominent citizens from the private sector who have distinguished themselves in their profession or fields of specialization of the University, members.\nThe Board shall appoint the two (2) prominent citizens from among a list of at least five (5) qualified persons in the Province of Sultan Kudarat, as recommended by the search committee constituted by the University President, in consultation with the Chairperson of the CHED and the other members of the Board, based on the normal standards and qualifications for the position.\nThe term of office of the President of the federation of faculty associations, the President of the federation of alumni associations shall be coterminous with their respective terms of office, as set forth in their respective constitutions and bylaws.\nThe two (2) prominent citizens shall serve for a term of two (2) years from the date of appointment."}},{"id":"PH-H8424-A6","no":6,"noLabel":{"en":"Section 6."},"text":{"en":"Promulgation and Implementation of Policies. - The Board shall promulgate and implement policies in accordance with the declared State policies on education and other pertinent provisions of the Philippine Constitution on education, agriculture, science and technology, as well as the policies, standards and thrusts of the CHED under Republic Act No. 7722, otherwise known as the \"Higher Education Act of 1994\"."}},{"id":"PH-H8424-A7","no":7,"noLabel":{"en":"Section 7."},"text":{"en":"Powers and Duties of the Board of Regents. - The Board shall have the following specific powers and duties, in addition to its general powers of administration and the exercise of all the powers granted to the board of directors of a corporation under existing laws:\n(a)To promulgate rules and regulations not contrary to law as may be necessary to carry out the purposes and functions of the University;\n(b)To receive and appropriate all sums as may be provided, for the support of the University in the manner it may determine in its discretion, in order to carry out the purposes and functions of the University;\n(c)To import duty-free economic, technical and cultural books and/or publications, upon certification by the CHED that such imported books and/or publications are for economic, technical, vocational, scientific, philosophical, historical or cultural purposes, in accordance with the provisions of the Tariff and Customs Code of the Philippines, as amended;\n(d)To receive in trust legacies, gifts and donations of real properties of all kinds and to administer and dispose of the same when necessary for the benefit of the University and, subject to the limitations, directions and instructions of the donor, if any.\nSuch donations shall be exempt from the donor's tax and the same shall be considered as allowable deductions from the gross income in the computation of the income tax of the donor, in accordance with the provisions of the National Internal Revenue Code (NIRC) of 1997, as amended: Provided, That such donations shall not be disposed of, transferred or sold;\n(e)To fix the tuition fees and other necessary school charges such as, but not limited to, matriculation fees, graduation fees and laboratory fees, as the Board may deem proper to impose, after due consultations with the involved sectors.\nSuch fees and charges, including government subsidies and other income generated by the University, shall constitute special trust funds and shall be deposited in any authorized government depository bank, and all interests that shall accrue therefrom shall form part of the same funds for the use of the University.\nAny provision of existing laws, rules and regulations to the contrary notwithstanding, any income generated by the University from tuition fees and other charges, as well as from the operation of auxiliary services and land grants, shall be retained by the University and may be disbursed by the Board for instruction, research, extension or other programs/projects of the University: Provided, That all fiduciary fees shall be disbursed for the specific purpose for which these are collected.\nIf, for reasons beyond its control, the University shall not be able to pursue any project for which funds have been appropriated and allocated under its approved program of expenditures, the Board may authorize the use of said funds for any reasonable purpose which, in its discretion, may be necessary and urgent for the attainment of the objectives and goals of the University;\n(f)To adopt and implement a socialized scheme of tuition and other school fees for greater access to poor by deserving students;\n(g)To authorize the construction or repair of its buildings, machinery, equipment and other facilities, and the purchase and acquisition of real and personal properties, including necessary supplies, materials and equipment;\n(h)To appoint, upon recommendation of the President of the University, Vice President, deans, directors, heads of departments, faculty members and other officials and employees of the University;\n(i)To fix and adjust salaries of faculty members and administrative officials and employees, subject to the provisions of the Revised Compensation and Position Classification System and other pertinent budget and compensation laws governing hours of service and such other duties and conditions as it may deem proper; to grant them, at its discretion, leaves of absence under such regulations as it may promulgate, any provision of existing law to the contrary notwithstanding; and to remove them for cause in accordance with the requirements of due process of law;\n(j)To approve the curricula, instructional programs and rules of discipline drawn by the Administrative and Academic Councils as herein provided;\n(k)To set policies on admission and graduation of students;\n(l)To award honorary degrees upon persons in recognition of their outstanding contribution in the fields of agriculture, public service, arts, science and technology, education or in any field of specialization within the academic competence of the University; and to authorize the awarding of certificates of completion of nondegree and nontraditional courses;\n(m)To establish and absorb nonchartered tertiary institutions within the Province of Sultan Kudarat as branches and extension centers of the University, in coordination with the CHED and in consultation with the Department of Budget and Management (DBM), and to offer therein programs or courses to promote and carry out equal and greater access to educational opportunities as mandated by the Constitution;\n(n)To establish research and extension centers of the University where such will promote the development of the latter;\n(o)To establish professorial chairs in the University and to provide fellowships for qualified faculty members and scholarships to deserving students;\n(p)To delegate any of its powers and duties provided for hereinabove to the President or Officer-in-Charge and/or other officials of the University as it may deem appropriate, so as to expedite the administration of the affairs of the University;\n(q)To authorize an external management audit of the University, to be financed by the CHED, subject to the rules and regulations of the Commission on Audit (COA); and to institute reforms, including academic and structural changes on the basis of the audit results and recommendations;\n(r)To collaborate with other governing boards of state universities and colleges within the Province of Sultan Kudarat or Region XII, under the supervision of the CHED and in consultation with the DBM, and work towards the restructuring of the University to become more efficient, relevant, productive and competitive;\n(s)To enter into joint ventures with business and industry for the profitable development and management of the economic assets of the University, the proceeds from which shall be used for the development and strengthening of the same;\n(t)To develop consortia and other forms of linkages with local government units (LGUs), institutions and agencies, both public and private, local and foreign, in furtherance of the purposes and objectives of the University;\n(u)To develop academic arrangements for institutional capability building with appropriate institutions and agencies, public and private, local and foreign, and to appoint experts/specialists as consultants, part-time or visiting or exchange professors, scholars or researchers, as the case may be;\n(v)To set up the adoption of modern and innovative modes of transmitting knowledge such as the use of information technology, the dual learning system, open learning or distance education and community laboratory for the promotion of greater access to higher education and graduate studies, as the case may be;\n(w)To establish policy guidelines and procedures for participative decision-making and transparency within the University;\n(x)To privatize, where most advantageous to the University, the management of nonacademic services such as health, food, building, grounds or property maintenance and such other similar activities; and (y)To extend the term of the President of the University beyond the age of retirement but not beyond the age of seventy (70), whose performance has been unanimously rated by the Board as outstanding, based on the guidelines, qualifications and/or standards set by the Board, after unanimous recommendation by the search committee."}},{"id":"PH-H8424-A8","no":8,"noLabel":{"en":"Section 8."},"text":{"en":"Meetings of the Board. - The Board shall regularly convene at least once every quarter. However, the Chairperson of the Board may, upon three (3)-days' prior written notice, call a maximum of two (2) special meetings whenever necessary.\nA quorum of the Board shall consist of majority of all its members holding office at the time of the meeting: Provided, however, That the Chairperson of the Board or the President of the University is among those present in the meeting.\nIn the absence of the Chairperson of the CHED, a Commissioner of the CHED, duly designated by him/her, shall represent him/her in the meeting with all the rights and responsibilities of a regular member: Provided, however, That during this meeting, the President of the University as Vice Chairperson shall be the Presiding Officer: Provided, further, that this proviso notwithstanding, the Chairperson of the CHED is hereby authorized to designate a CHED Commissioner as the regular Chair of the Board, in which case said CHED Commissioner shall act as the Presiding Officer.\nIn case the Chairpersons of the Congressional Committees on Education shall not be able to attend the Board meeting, they may duly designate their respective representatives to attend the said meeting, who shall have the same rights and responsibilities as a regular member of the Board.\nThe members of the Board shall not receive any salary but shall be entitled to reimbursements for actual and necessary expenses incurred, either in their attendance to meetings of the Board or in connection with other official business authorized by resolution of the Board, subject to existing laws and regulations."}},{"id":"PH-H8424-A9","no":9,"noLabel":{"en":"Section 9."},"text":{"en":"The University President. - The University shall be headed by a President, who shall render full-time service. He/She shall be appointed by the Board, subject to the guidelines, qualifications and/or standards set by the Board, upon recommendation of a duly constituted search committee. He/She shall have a term of four (4) years and shall be eligible for reappointment for another term: Provided, That in order to effect a smooth transition to a state university, the incumbent President of the Sultan Kudarat Polytechnic State College, if qualified, shall serve as the first President of the University.\nWithin six (6) months before the expiration of the term of office of the incumbent President of the University, the Board shall constitute the Search Committee for the Presidency (SCP).\nIn case of vacancy in the Office of the President by reason of death, compulsory retirement, resignation, removal for cause or incapacity of the President to perform the functions of his/her office, the Board shall designate an Officer-in-Charge of the University within sic (6) months from the date of vacancy, pending the appointment of a new President.\nIn case of vacancy in the Office of the President as mentioned in the immediately preceding paragraph, his/her successor or the Officer-in-Charge shall serve only the unexpired portion of the term.\nThe powers and duties of the President of the University, in addition to those specifically provided in this Act, shall be those usually pertaining to the Office of the President of similar universities, and those delegated by the Board.\nThe salary of the President of the University shall be in accordance with the Revised Compensation and Position Classification System and shall be comparable to that being received by the presidents of similar educational institutions.\nThe President of the University shall be assisted by the Vice President/s, who shall be appointed by the Board upon recommendation of the President."}},{"id":"PH-H8424-A10","no":10,"noLabel":{"en":"Section 10."},"text":{"en":"Heads of University Campuses. - Campus Directors shall head the University campuses and they shall render full-time service. They shall be appointed by the Board upon recommendation of the search committee and the University President, subject to the guidelines, qualifications and/or standards set by the Board: Provided, That the incumbent college administrators of the extension campuses shall serve as Campus Directors of their respective campuses."}},{"id":"PH-H8424-A11","no":11,"noLabel":{"en":"Section 11."},"text":{"en":"The Administrative Council. - There shall be an Administrative Council consisting of the President of the University as Chairperson, Vice Presidents, deans, directors and other officials of equal rank as members, whose duty is to review and recommend to the Board the policies governing the administration, management and development of the University for appropriate action."}},{"id":"PH-H8424-A12","no":12,"noLabel":{"en":"Section 12."},"text":{"en":"The Academic Council. - There shall be an Academic Council to be composed of the President of the University, who shall act as Chairperson, and all academic staff with the rank of at least an assistant professor, as members.\nThe Academic Council shall have the power to review and recommend the curricular offerings and rules of discipline of the University, subject to the appropriate action by the Board. It shall fix the requirements for the admission of students, as well as for their graduation and conferment of degrees, subject to review and/or approval by the Board through The President of the University. It shall have the disciplinary power over students of the University and shall formulate academic policies and rules and regulations on discipline, subject to the approval of the Board."}},{"id":"PH-H8424-A13","no":13,"noLabel":{"en":"Section 13."},"text":{"en":"The Secretary of the University. - The Board shall appoint a secretary, who shall serve as such for both the Board and the University and shall keep all records and proceedings of the Board. He/She serve upon each member of the Board the appropriate notice of the Board meetings."}},{"id":"PH-H8424-A14","no":14,"noLabel":{"en":"Section 14."},"text":{"en":"The Treasurer of the University. - The Treasurer of the Philippines shall be the ex officio treasurer of the University."}},{"id":"PH-H8424-A15","no":15,"noLabel":{"en":"Section 15."},"text":{"en":"The Faculty. No religious opinion or affiliation shall be a matter of inquiry in the appointment of faculty members of the University: Provided, That said appointment shall be subject to the guidelines, qualifications and/or standards set by the Board: Provided, further, That no member of the faculty shall teach for or against any particular church or religious sect."}},{"id":"PH-H8424-A16","no":16,"noLabel":{"en":"Section 16."},"text":{"en":"Scholarship Program/Admission. The University shall provide a scholarship program and other affirmative action programs to assist poor but deserving students who qualify for admission to the University.\nNo student shall be denied admission to the University by reason of sex, religion, cultural or community affiliation or ethnic origin."}},{"id":"PH-H8424-A17","no":17,"noLabel":{"en":"Section 17."},"text":{"en":"Academic Freedom and Institutional Autonomy. - The University shall enjoy academic freedom and institutional autonomy, pursuant to paragraph 2, Section 5 of Article XIV of the Constitution of the Republic of the Philippines."}},{"id":"PH-H8424-A18","no":18,"noLabel":{"en":"Section 18."},"text":{"en":"Authority to Loan or Transfer Apparatus/Equipment/Supplies and Detail of Personnel. - The heads of the bureaus and offices of the national government are hereby authorized to loan or transfer, upon the request of the President of the University, such apparatus, equipment or supplies as may be needed by the University, and to detail employees for duty therein when, in the judgment of the head of bureau or office, such apparatus, equipment, supplies or services of such employees can be spared without serious detriment to the public service.\nThe employees so detailed shall perform such duties as required of them by them by the President of the University, and the time so employed shall be counted as part of their regular services."}},{"id":"PH-H8424-A19","no":19,"noLabel":{"en":"Section 19."},"text":{"en":"Assets, Liabilities and Personnel. - All assets, fixed and movable, personnel and records of the Sultan Kudarat Polytechnic State College, as well as liabilities or obligations, are hereby transferred to the University: Provided, however, That the positions, rights and security of tenure of faculty members and personnel therein employed under existing laws prior to the conversion into a University shall be respected.\nAll parcels of land belonging to the government and occupied by the Sultan Kudarat Polytechnic State College are hereby declared to be property of the University, and shall be titled under that name: Provided, That should the University cease to exist or be abolished, or should such parcels of land aforementioned be no longer needed by the University, the same shall revert to the LGUs concerned."}},{"id":"PH-H8424-A20","no":20,"noLabel":{"en":"Section 20."},"text":{"en":"Appropriations. - The amount necessary to carry out the provisions of this Act shall be charged against the current year's appropriations of the Sultan Kudarat Polytechnic State College, except the sums needed to continue the operations of the existing high schools. Thereafter, such sums as may be necessary for the continued operation and maintenance of the Sultan Kudarat State University shall be included in the annual General Appropriations Act."}},{"id":"PH-H8424-A21","no":21,"noLabel":{"en":"Section 21."},"text":{"en":"Development Plan, Management Audit, Organizational/Administrative/Academic Structure. - Within the period of one hundred twenty (120) days after the approval of this Act, the University shall accomplish the following:\n(a)Submit a five (5)-year development plan, including its corresponding program budget to the CHED, for corresponding recommendation to the DBM;\n(b)Undergo a management audit in cooperation with the CHED; and (c)Accordingly set up its organizational, administrative as well as academic structure, including the appointment of the key officials of the University."}},{"id":"PH-H8424-A22","no":22,"noLabel":{"en":"Section 22."},"text":{"en":"CHED Monitoring and Evaluation. - The CHED shall conduct regular monitoring and evaluation to determine continuing compliance with requirements on university status. In the event that the Commission finds that the university does not maintain compliance thereof, it shall submit the appropriate recommendation for the revocation of the university status to the Senate Committee on Education, Arts and Culture, and the House Committee on Higher and Technical Education."}},{"id":"PH-H8424-A23","no":23,"noLabel":{"en":"Section 23."},"text":{"en":"Filing of Report. - On or before the fifteenth (15th) day of the second (2nd) month after the opening of the regular classes each year, the Board shall file with the Office of the President of the Philippines, through the Chairperson of the CHED and with both Houses of Congress, a detailed report on the progress, conditions and needs of the University."}},{"id":"PH-H8424-A24","no":24,"noLabel":{"en":"Section 24."},"text":{"en":"Suppletory Application. - The provisions of Republic Act No. 8292, otherwise known as the \"Higher Education Modernization Act of 1997\", shall be an integral part of this Act and shall serve as part of the Governing Charter of the University."}},{"id":"PH-H8424-A25","no":25,"noLabel":{"en":"Section 25."},"text":{"en":"Parity Clause. - All other powers, functions and privileges, responsibilities and limitations to state universities and/or their officials under existing laws shall be deemed granted to or imposed upon the University and/or its officials, whenever appropriate."}},{"id":"PH-H8424-A26","no":26,"noLabel":{"en":"Section 26."},"text":{"en":"Implementing Rules and Regulations. - The Board, in consultation with the CHED, shall formulate the guidelines to fully implement the provisions of this Act."}},{"id":"PH-H8424-A27","no":27,"noLabel":{"en":"Section 27."},"text":{"en":"Separability Clause. - If, for any reason, any part or provision of this Act is declared invalid or unconstitutional, the remaining parts or provisions not affected thereby shall remain in full force and effect."}},{"id":"PH-H8424-A28","no":28,"noLabel":{"en":"Section 28."},"text":{"en":"Repealing Clause. - All laws, presidential decrees, executive orders, rules and regulations contrary to or inconsistent with the provisions of this Act are hereby repealed or modified accordingly."}},{"id":"PH-H8424-A29","no":29,"noLabel":{"en":"Section 29."},"text":{"en":"Effectivity. - This Act shall take effect fifteen (15) days after its publication in two (2) newspapers of general circulation."}}],"pack":"ph-p120"};
  FT["PH-H8425"] = {"id":"PH-H8425","coverage":"full","language":"en","sourceName":"LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation）","sourceUrl":"https://lawphil.net/statutes/repacts/ra2010/ra_9967_2010.html","fetchedAt":"2026-10-06","articleCount":5,"structureMode":"ARTICLE","title":{"zh":"对第 3207 号共和国法的修改","en":"An Act Further Amending the Franchise of San Fernando Electric Light and Power Company, Inc. Granted Under Republic Act No. 3207, as Amended, to Construct, Operate and Maintain a Distribution System for the Conveyance of Electric Power to the End-Users in the City of San Fernando, the Municipality of Floridablanca and Barangays Talang and Ligaya in the Municipality of Guagua, All in the Province of Pampanga, and Renewing/Extending the Term of the Franchise to Another Twenty-Five (25) Years From the Date of Approval of This Act","orig":"An Act Further Amending the Franchise of San Fernando Electric Light and Power Company, Inc. Granted Under Republic Act No. 3207, as Amended, to Construct, Operate and Maintain a Distribution System for the Conveyance of Electric Power to the End-Users in the City of San Fernando, the Municipality of Floridablanca and Barangays Talang and Ligaya in the Municipality of Guagua, All in the Province of Pampanga, and Renewing/Extending the Term of the Franchise to Another Twenty-Five (25) Years From the Date of Approval of This Act"},"level":"law","status":"active","topics":["investment","energy","administrative"],"docNumber":"Republic Act No. 9967","issuingBody":"Congress of the Philippines","promulgatedDate":"2010-02-06","completenessNote":"全文，共 5 条；逐字取自 LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation） 官方页面（statutes/repacts/ra2010/ra_9967_2010.html），未改写、未摘译、未节选；原文语言：英语。 条文抬头依源文为 “Section N.” 等形式，本库统一规范为 “Section N.”；首行抬头与条内标题的分段依源文块级边界还原。","country":"PH","countryName":"菲律宾","layer":"intl","articles":[{"id":"PH-H8425-A1","no":1,"noLabel":{"en":"Section 1."},"text":{"en":"Republic Act No. 3207, as amended, granting a franchise to San Fernando Electric Light and Power Company, Inc. is hereby further amended to read as follows:\n\"Section 1. Nature and Scope of Franchise. - Subject to the provisions of the Constitution and applicable laws, rules and regulations, there is hereby granted to San Fernando Electric Light and Power Company, Inc., hereunder referred to as the grantee, its successors or assigns, a franchise to construct, operate and maintain in the public interest and for commercial purposes, a distribution system for the conveyance of electric power to the end-users in the City of San Fernando, the Municipality of Floridablanca and barangays Talang and Ligaya in the Municipality of Guagua, all in the Province of Pampanga.\n\"As used in this Act, distribution system refers to the system of wire and associated facilities including sub-transmission lines belonging to a franchised distribution utility extending between the delivery point on the point on the national transmission system or generating facility and the metering point/facility of the end-user.\"\n\"Section 2. Manner of Operations of Facilities. - All electric distribution facilities, lines and systems for electric services owned, maintained, operated or managed by the grantee, its successors or assigns, shall be operated and maintained at all times in a superior manner, and it shall be the duty of the grantee, its successors or assigns, whenever required to do so by the Energy Regulatory Commission, hereafter referred to as the ERC, or its legal successor, or the Department of Energy, hereinafter referred to as the DOE, or its legal successor, or any other government agency concerned, to modify, improve and change such facilities or systems in such manner and to such extent as the progress in science and improvements in the electric power services may render reasonable and proper.\n\"Whenever practicable and for purposes of maintaining order, safety and aesthetics along the highways, roads, streets, alleys or right-of-way, the grantee may allow the use of free spaces in its poles, facilities or right-of-wy by interested parties upon reasonable compensation to the grantee considering costs incurred to accommodate and administer the use of the grantee's facilities by such parties. The ERC shall decide in case of dispute or disagreement between the parties.\"\n\"Section 3. Authority of the Energy Repulatory Commission (ERC). - The grantee shall secure from the ERC, or any other government agency which has jurisdiction over the operation of the herein grantee, the necessary certificate of public convenience and necessity and other appropriate permits and licenses for the construction and operation of its electric distribution system.\"\n\"Section 4. Ingress and Egress. - For the purpose of erecting and maintaining poles and other supports for the said facilities, wires or other conductors or for the purpose of laying and maintaining said facilities, wires, cables or other conductors, it shall be lawful for the grantee, its successors or assigns, with the prior approval of the Department of Public Works and Highways (DPWH) or the local government units (LGUs) concerned, as may be appropriate, to make excavations or lay conduits in any of the public places, highways, streets, lanes, alleys, avenues, sidewalks or bridges of said provinces and/or municipalities: Provided, however, That any public place, highways, street, lane, alleys, avenue, sidewalk or bridge disturbed, altered or changed by reason of the erection of poles or other supports, or the laying of wires, other conductors or conduits, shall be immediately repaired and properly restored at the expense of the grantee, its successors or assigns, in accordance with the standards set by the DPWH and LGUs.\"\n\"Section 5. Responsibility to the Public. - The grantee shall supply electricity to its captive market in the least cost manner. In the interest of the public good and as far as feasible and whenever required by the ERC, the grantee shall modify, improve or change its facilities, poles, lines, systems and equipment for the purpose of providing efficient and reliable service and reduced electricity costs. The grantee shall charge reasonable and just power rates for its services to all types of consumers within its franchised areas in order that business and industries shall be able to compete.\n\"The grantee shall have the obligation to provide open and non-discriminatory access to its distribution system and services for any end-user within its franchise area consistent with Republic Act No. 9136, otherwise known as 'Electric Power Industry Reform Act of 2001'. The grantee shall not engage in any activity that will constitute an abuse of market power such as, but not limited to, unfair trade practices, monopolistic schemes and any other activities that will hinder competitiveness of businesses and industries.\"\n\"Section 6. Rates for Services. - The retail rates to its captive market and charges for the distribution of electric power by the grantee to its end-user shall be regulated by and subject to the approval of the ERC or its legal successor.\n\"The grantee shall identify and segregate in its electricity bill to the end-users the components of the retail rate pursuant to Republic Act No. 9136, unless otherwise amended. Such rates charged by the grantee to the end-users shall be made public and transparent. The grantee shall implement lifeline rate to marginalized end-users as mandated under Republi Act No. 9136.\"\n\"Section 7. Promotion of Consumers Interests. - The herein grantee shall establish a consumer desk that will handle consumer complaints and ensure adequate promotion of consumer interests. The grantee shall act with dispatch on all complaints brought before it.\"\n\"Section 8. Right of the Government. - A special right is hereby reserved to the President of the Philippines in times of war, rebellion, public peril, calamity, emergency, disaster, or disturbance of peace and order to take over and operate the distribution system of the grantee or to authorize the temporary use and operation thereof by any agency/department of the government upon due compensation to the grantee for the use of the said distribution system during the period when they shall be so operated.\"\n\"Section 9. Tax Provision. - In consideration of the franchise and rights hereby granted, the grantee, its successors or assigns, shall pay a franchise tax, which may be amended from time to time and is currently at the rate of and equivalent to fifty percent (50%) of one percent (1%) of all revenues derived by the grantee from its distribution wheeling services and captive market supply, excluding generation charge, transmission charge and system loss charge: Provided, That nothing herein shall be construed as repealing any tax exemptions, incentives or privileges granted under any relevant law: Provided, further, That the grantee, its successors or assigns, shall be liable to pay real property taxes only on their real estate and buildings, exclusive of this franchise, as other corporations are now or hereafter may be required by law to pay.\n\"The grantee shall file the return with the city where its principal place of office is located and pay the taxes due thereon to the Commissioner of Internal Revenue or his duly authorized repersentative in accordance with the National Internal Revenue Code (NIRC) and the return shall be subject to audit by the bureau of Internal Revenue.\"\n\"Section 10. Right of Eminent Domain. - Subject to the limitations and procedures prescribed by law, the grantee is authorized to exercise the right of eminent domain insofar as it may be reasonably necessary for the efficient maintenance and operation of services. The grantee is authorized to install and maintain its poles, wires and other facilities over and across public property, including streets, highways, forest reserves and other similar property of the Government of the Philippines, its branches or any of its instrumentalities. The grantee may acquire such private property as is actually necessary for the realization of the purposes for which this franchise is granted: Provided, That proper condemnation proceedings shall have been instituted and just compensation paid.\"\n\"Section 11. Warranty in Favor of National and Local Governments. - The grantee shall hold the national, provincial and municipal governments of the Philippines harmless from all claims, accounts, demands or actions arising out of accidents or injuries, whether to property or persons, caused by the construction, installation, operation and maintenance of the distribution system of the grantee.\"\n\"Section 12. Liability for Damages. - The grantee shall be liable for any injury and damage arising from or caused by accident to persons and property by reason of any defective construction under this franchise or of any neglect or omission to keep its poles and wires in a safe condition.\"\n\"Section 13. Sale, Lease, Transfer, Usufruct, etc. - The grantee shall not lease, transfer, grant the usufruct of or sell this franchise or the rights and privileges acquired thereunder to any person, firm, company, corporation or other commercial or legal entity, nor merge with any other corporation or entity, nor shall the controlling interest of the grantee be transferred, whether in whole or in part, and whether simultaneoustly or contemporaneously, to any such person, firm, company, corporation or entity without the prior approval of the Congress of the Philippines. Any person or entity to which tis franchise is sold, transferred or assigned, shall be subject to the same conditions, terms, restrictions and limitations of this Act.\"\n\"Section 14. Equality Clause. - In the event that any competing individual, partnershio or corporation shall receive a similar permit or franchise with terms and/or provisions more favorable than those herein granted or which tend to place the herein grantee at any disadvantage, such terms and/or provisions shall be deemed part hereof and shall operate equally in favor of the herein grantee: Provided, That any terms and/or provisions herein granted which are not contained in other frachises that may hereafter be granted shall likewise be enjoyed by the future grantees: Provided, however, That the foregoing shall neither apply to nor affect the provisions concerning territory covered by the franchise and the life span of the franchise.\"\n\"Section 15. Separability Clause. - If for any reason, any of the sections or provisions of this Act is declared unconstitutional or invalid, the other parts or provisions hereof which are not affected thereby shall continue to be in full force and effect.\"\n\"Section 16. Applicability Clause. - The grantee shall comply with and be subject to the provisions of Commonwealth Act No. 146, as amended, otherwise known as the 'Public Service Act' and Republic Act No. 9136, otherwise known as the 'Electric Power Industry Reform Act of 2001'.\"\n\"Section 17. Repealability and Nonexclusivity Clause. - This franchise shall be subject to amendment, alteration or repeal by the Congress of the Philippines when the public interest so requires and shall not be interpreted as an exclusive grant of the privileges herein provided for.\"\n\"Section 18. Reportorial Requirement. - The grantee shall submit an annual report of finances and operations to the Congress of the Philippines.\""}},{"id":"PH-H8425-A2","no":2,"noLabel":{"en":"Section 2."},"text":{"en":"Renewal/Extension of the Term of Franchise. - This franchise shall be for a term of twenty-five (25) years from the date of effectivity of this Act. This franchise shall be deemed ipso facto revoked in the event that the grantee fails to operate continuously for two (2) years."}},{"id":"PH-H8425-A3","no":3,"noLabel":{"en":"Section 3."},"text":{"en":"Acceptance and Compliance. - Acceptance of the amendment and extension/renewal of the franchise shall be given in writing within sixty (60) days from the date of effectivity of this Act."}},{"id":"PH-H8425-A4","no":4,"noLabel":{"en":"Section 4."},"text":{"en":"Repealing Clause. - All laws, decrees, orders, resolutions, instruction and rules and regulations or parts thereof, which are inconsistent with this Act, are hereby deemed repealed or modified accordingly."}},{"id":"PH-H8425-A5","no":5,"noLabel":{"en":"Section 5."},"text":{"en":"Effectivity Clause. - This Act shall take effect fifteen (15) days after its publication in at least two (2) newspapers of general circulation."}}],"pack":"ph-p120"};
  FT["PH-H8426"] = {"id":"PH-H8426","coverage":"full","language":"en","sourceName":"LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation）","sourceUrl":"https://lawphil.net/statutes/repacts/ra2010/ra_9968_2010.html","fetchedAt":"2026-10-06","articleCount":5,"structureMode":"ARTICLE","title":{"zh":"对第 3118 号共和国法的修改","en":"An Act Amending Act No. 3118, Granting a Franchise to Cabanatuan Electric Corporation (Formerly Samahang Magsasaka, Incorporada), to Construct, Operate and Maintain a Distribution System for the Conveyance of Electric Power to the End-Users in the City of Cabanatuan, Province of Nueva Ecija, and Renewing/Extending the Term of the Franchise to Another Twenty-Five (25) Years From the Date of Approval of This Act","orig":"An Act Amending Act No. 3118, Granting a Franchise to Cabanatuan Electric Corporation (Formerly Samahang Magsasaka, Incorporada), to Construct, Operate and Maintain a Distribution System for the Conveyance of Electric Power to the End-Users in the City of Cabanatuan, Province of Nueva Ecija, and Renewing/Extending the Term of the Franchise to Another Twenty-Five (25) Years From the Date of Approval of This Act"},"level":"law","status":"active","topics":["investment","energy"],"docNumber":"Republic Act No. 9968","issuingBody":"Congress of the Philippines","promulgatedDate":"2010-02-06","completenessNote":"全文，共 5 条；逐字取自 LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation） 官方页面（statutes/repacts/ra2010/ra_9968_2010.html），未改写、未摘译、未节选；原文语言：英语。 条文抬头依源文为 “Section N.” 等形式，本库统一规范为 “Section N.”；首行抬头与条内标题的分段依源文块级边界还原。","country":"PH","countryName":"菲律宾","layer":"intl","articles":[{"id":"PH-H8426-A1","no":1,"noLabel":{"en":"Section 1."},"text":{"en":"Republic Act No. 3118, granting a franchise to Cabanatuan Electric Corporation, (formerly Samahang Magsasaka, Incorporada ) is hereby amended to read as follows:\n\"Section 1. Nature and Scope of Franchise. - Subject to the provisions of the Constitution and applicable laws, rules and regulations, there is hereby granted to Cabanatuan Electric Corporation (formerly Samahang Magsasaka, Incorporada ), hereunder referred to as the grantee, its successors or assigns, a franchise to construct, operate and maintain in the public interest and for commercial purposes, a distribution system for the conveyance of electric power to the end-users in the City of Cabanatuan, Province of Nueva Ecija.\n\"As used in this Act, distribution system refers to the system of wires and associated facilities including sub-transmission lines belonging to a franchised distribution utility extending between the delivery point on the national transmission system or generating facility and the metering point/facility of the end-user.\"\n\"Section 2. Manner of Operations of Facilities. - All electric distribution facilities, lines and systems for electric services owned, maintained, operated or managed by the grantee, its successors or assigns, shall be operated and maintained at all times in a superior manner, and it shall be the duty of the grantee, its successor or assigns, whenever required to do so by the Energy Regulatory Commission, hereafter referred to as the ERC, or its legal successor, or the Department of Energy, hereinafter referred to as the DOE, or its legal successor, or any other government agency concerned, to modify, imporve and change such facilities or systems in such manner and to such extent as the progress in science and improvements in the electric power services may render reasonable and proper.\n\"Whenever practicable and for purposes of maintaining order, safety and aesthetics along the highways, roads, streets, alleys or right-of-way by interested parties upon reasonable compensation to the grantee considering costs incurred to accomodate and administer the use of the grantee's facilities by such parties. The ERC shall decide in case of dispute or disagreement between the parties.\"\n\"Section 3. Authority of the Energy Regulatory Commission (ERC). - The grantee shall secure from the ERC, or any other government agency which has jurisdiction over the operation of the herein grantee, the necessary certificate of public convenience and necessity and other appropriate permits and licenses for the construction and operation of its electric distribution system.\"\n\"Section 4. Ingress and Egress. - For the purpose of erecting and maintaining poles and other supports for said facilities, wires or other conductors or for the purpose of laying and maintaining said facilities, wires, cables or other conductors, it shall be lawful for the grantee, its successors or assigns, with the prior approval of the Department of Public Works and Highways (DPWH) or the local government units (LGUs) concerned, as may be appropriate, to make excavations or lay conduits in any of the public places, highways, street, lanes, alleys, avenues, sidewalks or bridges of said provinces and/or municipalities: Provided, however, That any public place, highway, street, lane, alley, avenue, sidewalk or bridge distubed, altered or changed by reason of the erection of poles or other supports, or the laying of wires, other conductors or conduits, shall be immediately repaired and properly restored at the expense of the grantee, its successors or assigns, in accordance with the standards set by the DPWH and LGUs.\n\"Section 5. Responsibility to the Public. - The grantee shall supply electricity to its captive market in the least-cost manner. In the interest of the public good and as far as feasible and whenever required by the ERC, the grantee shall modify, improve or change its facilities, poles, lines, systems and equipment for the purpose of providing efficient and reliable service and reduced electricity costs. The grantee shall charge reasonable and just power rates for its services to all types of consumers within its franchised areas in order that business and industries shall be able to compete.\n\"The grantee shall have the obligation to provide open and nondiscriminatory access to its distribution system and services for any end-user within its franchise area consistent with Republic Act No. 9136, otherwise known as the 'Electric Power Industry Reform Act of 2001'. The grantee shall not engage in any activity that will constitute an abuse of market power such as, but not limited to, unfair trade practices, monopolistic schemes and any other activities that will hinder competitiveness of businesses and industries.\"\n\"Section 6. Rates for Services. - The retail rates to its captive market and charges for the distribution of electric power by the grantee to its end-user shall be regulated by and subject to the approval of the ERC or its legal successor.\n\"The grantee shall identify and segregate in its electric bill to the end-users the components of the retail rate pursuant to Republic Act No. 9136, unless otherwise amended. Such rates charged by the grantee to the end-users shall be made public and transparent. The grantee shall implement lifeline rate to marginalized end-users as mandated under Republic Act No. 9136.\"\n\"Section 7. Promotion of Consumer Interests. - the herein grantee shall establish a consumer desk that will handle consumer complaints and ensure adequate promotion of consumer interests. The grantee shall act with dispatch on all complaints brought before it.\"\n\"Section 8. Right of the Government. - A special right is hereby reserved to the President of the Philippines in times of war, rebellion, public peril, calamity, emergency, disaster or disturbance of peace and order to take over and operate the distribution system of the grantee or to authorize the temporary use and operation thereof by any agency/department of the government upon due compensation to the grantee for the use of the said distribution system during the period when they shall be so operated.\"\n\"Section 9. Tax Provision. - In consideration of the franchise and rights hereby granted, the grantee, its successors or assigns, shall pay a franchise tax, which may be amended from time to time and is currently at the rate of and equivalent to fifty percent (50%) of one percent (1%) of all revenues derived by the grantee from its distribution wheeling services and captive market supply, excluding generation charge, transmission charge and system loss charge: Provided, that nothing herein shall be construed as repealling any tax exemptions, incentives or privileges granted under any relevant law: Provided, further, That the grantee, its successors or assigns, shall be liable to pay real property taxes only on their real estate and buildings, exclusive of this franchise, as other corporations are now or hereafter may be required by law to pay.\n\"The grantee shall file the return with the city where its principal place of office is located and pay the taxes due thereon to the Commissioner of Internal Revenue or his duly authorized representative in accordance with the National Internal Revenue Code (NIRC) and the return shall be subject to audit by the Bureau of Internal Revenue.\"\n\"Section 10. Right of Eminent Domain. - Subject to the lilmitations and procedures prescribed by law, the grantee is authorized to exercise the right of eminent domain insofar as it may be reasonably necessary for the efficient maintenance and operation of services. The grantee is authorized to install and maintain its poles, wires and other facilities over and across public property, including streets, highways, forest reserves and other similar property of the Government of the Philippines, its branches or any of its instrumentalities. The grantee may acquire such private property as is actually necessary for the realization of the purposes for which this franchise is granted: Provided, That proper condemnation proceedings shall have been instituted and just compensation paid.\"\n\"Section 11. Warranty in Favor of National and Local Governments. - The grantee shall hold the national, provincial and municipal governments of the Philippines harmless from all claims, accounts, demands or actions arising out of accidents or injuries, whether to property or persons, caused by the construction, installation, operation and maintenance of the distribution system of the grantee.\"\n\"Section 12. Liability for Damages. - The grantee shall be liable for any injury and damage arising from or caused by accident to persons and property by reason of any defective construction under this franchise or of any neglect or omission to keep its poles and wires in a safe condition.\"\n\"Section 13. Sale, Lease, Transfer, Usufruct, etc. - The grantee shall not lease, transfer, grant the usufruct of, or sell this franchise or the rights and privileges acquired thereunder to any person, firm, company, corporation or other commercial or legal entity, nor merge with any other corporation or entity, nor shall the controlling interest of the grantee be transferred, whether in whole or in part, and whether simultaneously or contemporaneously, to any such person, firm, company, corporation or entity without the prior approval of the Congress of the Philippines. Any person or entity to which this franchise is sold, transferred or assigned, shall be subject to the same conditions, terms, restrictions and limitations of this Act.\"\n\"Section 14. Equality Clause. - In the event that any competing individual, partnership or corporation shall receive a similar permit or franchise with terms and/or provisions more favorable than those herein granted or which tend to place the herein grantee at any disadvantage, such terms and/or provisions shall be deemed part hereof and shall operate equally in favor of the herein grantee: Provided, That any terms and/or provisions herein granted which are not contained in other franchises that may hereafter be granted shall likewise be enjoyed by the future grantees: Provided, however, That the foregoing shall neither apply to nor affect the provisions concerning territory covered by the franchise and the life span of the franchise.\"\n\"Section 15. Reportorial Requirement. - The grantee shall submit an annual report of finances and operations to the Congress of the Philippines.\"\n\"Section 16. Applicability Clause. - The grantee shall comply with and be subject to the provisions of Commonwealth Act No. 146, as amended, otherwise known as the 'Public Services Act' and Republic Act No. 9136, otherwise known as the 'Electric Power Industry Reform Act of 2001'.\"\n\"Section 17. Repealability and Nonexclusivity Clause. - This franchise shall be subject to amendment, alteration or repeal by the Congress of the Philippines when the public interest so requires and shall not be interpreted as an exclusive grant of the privileges herein provided for.\"\n\"Section 18. Separability Clause. - If for any reason, any of the secions or provisions of this Act is declared unconstitutional or invalid, the other parts or provisions hereof which are not affected thereby shall continue to be in full force and effect.\""}},{"id":"PH-H8426-A2","no":2,"noLabel":{"en":"Section 2."},"text":{"en":"Renewal/Extension of the Term of Franchise. - This franchise shall be for a term of twenty-five (25) years from the date of effectivity of this Act. This franchise shall be deemed ipso facto revoked in the event that the grantee fails to operate continuously for two (2) years."}},{"id":"PH-H8426-A3","no":3,"noLabel":{"en":"Section 3."},"text":{"en":"Acceptance and Compliance. - Acceptance of the amendment and extension/renewal of this franchise shall be given in writing within sixty (60) days from the date of effectivity of this Act."}},{"id":"PH-H8426-A4","no":4,"noLabel":{"en":"Section 4."},"text":{"en":"Repealing Clause. - All laws, decrees, orders, resolutions, instructions and rules and regulations or parts thereof, which are inconsistent with this Act, are hereby deemed repealed or modified accrodingly."}},{"id":"PH-H8426-A5","no":5,"noLabel":{"en":"Section 5."},"text":{"en":"Effectivity Clause. - This Act shall take effect fifteen (15) days after its publication in at least two (2) newspapers of general circulation."}}],"pack":"ph-p120"};
  FT["PH-H8427"] = {"id":"PH-H8427","coverage":"full","language":"en","sourceName":"LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation）","sourceUrl":"https://lawphil.net/statutes/repacts/ra2010/ra_9969_2010.html","fetchedAt":"2026-10-06","articleCount":5,"structureMode":"ARTICLE","title":{"zh":"对第 3221 号共和国法的修改","en":"An Act Amending Republic Act No. 3221, Granting a Franchise to Dagupan Electric Corporation to Construct, Operate and Maintain a Distribution System for the Conveyance of Electric Power to the End-Users in the City of Dagupan, the Municipalities of Calasiao, Sta. Barbara, San Fabian, San Jacinto and Manaoag, and Barangays Bolingit and Cruz in the City of San Carlos, All in the Province of Pangasinan, and Renewing/Extending the Term of the Franchise to Another Twenty-Five (25) Years From the Date of the Approval of This Act","orig":"An Act Amending Republic Act No. 3221, Granting a Franchise to Dagupan Electric Corporation to Construct, Operate and Maintain a Distribution System for the Conveyance of Electric Power to the End-Users in the City of Dagupan, the Municipalities of Calasiao, Sta. Barbara, San Fabian, San Jacinto and Manaoag, and Barangays Bolingit and Cruz in the City of San Carlos, All in the Province of Pangasinan, and Renewing/Extending the Term of the Franchise to Another Twenty-Five (25) Years From the Date of the Approval of This Act"},"level":"law","status":"active","topics":["investment","energy","administrative"],"docNumber":"Republic Act No. 9969","issuingBody":"Congress of the Philippines","promulgatedDate":"2010-02-06","completenessNote":"全文，共 5 条；逐字取自 LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation） 官方页面（statutes/repacts/ra2010/ra_9969_2010.html），未改写、未摘译、未节选；原文语言：英语。 条文抬头依源文为 “Section N.” 等形式，本库统一规范为 “Section N.”；首行抬头与条内标题的分段依源文块级边界还原。","country":"PH","countryName":"菲律宾","layer":"intl","articles":[{"id":"PH-H8427-A1","no":1,"noLabel":{"en":"Section 1."},"text":{"en":"Republic Act No. 3221, granting a franchise to Dagupan Electric Corporation, is hereby amended to read as follows:\n\"Section 1. Nature and Scope of Franchise. - Subject to the provisions of the Constitution and applicable laws, rules and regulations, there is hereby granted to Dagupan Electric Corporation, hereunder referred to as the grantee, its successors or assigns, a franchise to construct, operate and maintain in the public interest and for commercial purposes, a distribution system for the conveyance of electric power to the end-users in the City of Dagupan, the municipalities of Calasiao, Sta. Barbara, San Fabian, San Jacinto and Manaoag, and barangays Bolingit and Cruz in the City of San Carlos, all in the Province of Pangasinan.\n\"As used in this Act, distribution system refers to the system of wires and associated facilities including subtransmission lines belonging to a franchised distribution utility extending between the delivery point on the national transmission system or generating facility and the metering point/facility of the end-user.\"\n\"Section 2. Manner of Operations of Facilities. - All electric distribution facilities, lines and systems for electric services owned, maintained, operated or managed by the grantee, its successor or assigns, shall be operated and maintained at all times in a superior manner, and it shall be the duty of the grantee, its successor or assigns, whenever required to do so by the Energy Regulatory Commission hereafter referred to as the ERC, or its legal successor; or the Department of Energy, hereinafter referred to as the DOE, or its legal successor, or any other government agency concerned, to modify, improve and change such facilities or systems in such manner and to such extent as the progress in science and improvements in the electric power services may render reasonable and proper.\n\"Whenever practicable and for purposes of maintaining order, safety and aesthetics along the highways. roads streets, alleys or right-of-way by interested parties upon reasonable compensation to the grantee considering costs incurred to accommodate and administer the use of the grantee's facilities by such parties. The ERC shall decide in case of dispute or disagreement between the parties.\"\n\"Section 3. Authority of the Energy Regulatory Commission (ERC). - The grantee shall secure from the ERC, or any other government agency which has jurisdiction over the operation of the herein grantee, the necessary certificate of public convenience and necessity and other appropriate permits and licenses for the construction and operation of its electric distribution system.\"\n\"Section 4. Ingress and Egress. - For the purpose of erecting and maintaining poles and other supports for said facilities, wires or other conductors or for the purpose of laying and maintaining said facilities, wires, cables or other conductors, it shall be lawful for the grantee, its successors or assigns, with the prior approval of the Department of Public Works and Highways (DPWH) or the local government units (LGUs) concerned, as may be appropriate, to make excavations or lay conduits in any of the public places, highways, streets, lanes, alleys, avenue, sidewalks or bridges of said provinces and/or municipalities: Provided, however, That any public place, highways, street, lane, alley, avenue, sidewalk or bridge disturbed, altered or changed by reason of the erection of poles or other supports, or the laying of wires, other conductors or conduits shall be immediately repaired and properly restored at the expense of the grantee, its successors or assigns, in accordance with the standards set by the DPWH and the LGUs.\"\n\"Section 5. Responsibility to the Public. - The grantee shall supply electricity to its captive market in the least-cost manner. In the interest of the public good and as far as feasible and whenever required by the ERC, the grantee shall modify, improve or change its facilities, poles, lines, systems and equipment for the purpose of providing efficient and reliable service and reduced electricity costs. The grantee shall charge reasonable and just power rates for its services to all types of consumers within its franchised areas in order that business and industries shall be able to compete.\n\"The grantee shall have the obligation to provide open and nondiscriminatory access to its distribution system and services for any end-user within its franchise area consistent with Republic Act No. 9136, otherwise known as 'Electric Power Industry Reform Act of 2001'. The grantee shall not engage in any activity that will constitute an abuse of market power such as, but not limited to, unfair trade practices, monopolistic schemes any other activities that will hinder competitiveness of businesses and industries.\"\n\"Section 6. Rates for Services. - The retail rates to its captive market and charges for the distribution of electric power by the grantee to its end-users shall be regulated by and subject to the approval of the ERC or its legal successor.\n\"The grantee shall identify and segregate in its electricity bill to the end-users the components of the retail rate pursuant to Republic Act No. 9136, unless otherwise amended. Such rates charged by the grantee to the end-users shall be made public and transparent. The grantee shall implement lifeline rate to marginalized end-users as mandated under Republic Act No. 9136.\"\n\"Section 7. Promotion of Consumer Interests. - The herein grantee shall establish a consumer desk that will handle consumer complaints and ensure adequate promotion of consumer interests. The grantee shall act with dispatch on all complaints brought before it.\"\n\"Section 8. Right of the Government. - A special right is hereby reserved to the President of the Philippines in times of war, rebellion, public peril, calamity, emergency, disaster or disturbance of peace and order to take over and operate the distribution system of the grantee or to authorize the temporary use and operation thereof by any agency/department of the government upon due compensation to the grantee for the use of the said distribution system during the period when they shall be so operated.\"\n\"Section 9. Tax Provision. - In consideration of the franchise and rights hereby granted, the grantee, its successors or assigns, shall pay a franchise tax, which may be amended from time to time and is currently at the rate of and equivalent to fifty percent (50%) of one percent (1%) of all revenues derived by the grantee from its distribution wheeling services and captive market supply, excluding generation charge, transmission charge and system loss charge: Provided, That nothing herein shall be construed as repealing any tax exemptions, incentives or privileges granted under any relevant law: Provided, further, That the grantee, its successors or assigns, shall be liable to pay real property taxes only on their real estate and buildings, exclusive of the franchise, as other corporations are now or hereafter may be required by law to pay.\n\"The grantee shall file the return with the city where its principal place of office is located and pay the taxes due thereon to the Commissioner of Internal Revenue or his duly authorized representative in accordance with the National Internal Revenue Code (NIRC) and the return shall be subject to audit by the Bureau of Internal Revenue.\"\n\"Section 10. Right of Eminent Domain. - Subject to the limitations and procedures prescribed by law, the grantee is authorized to exercise the right of eminent domain insofar as it may be reasonably necessary for the efficient maintenance and operation of services. The grantee is authorized to install and maintain its poles, wires and other facilities over and across public property, including streets, highways, forest reserves and other similar property of the Government of the Philippines, its branches or any of its instrumentalities. The grantee may acquire such private property as is actually necessary for the realization of the purposes for which this franchise is granted: Provided, That proper condemnation proceedings shall have been instituted and just compensation paid.\"\n\"Section 11. Warranty in Favor of National and Local Governments. - The grantee shall hold the national, provincial and municipal governments of the Philippines harmless from all claims, accounts, demands or actions arising out of accidents or injuries, whether to property or persons, caused by the construction, installation, operation and maintenance of the distribution system of the grantee.\"\n\"Section 12. Liability for Damages. - The grantee shall be liable for any injury and damage arising from or caused by accident to persons and property by reason of any defective construction under this franchise or of any neglect or omission to keep its poles and wires in a safe condition.\"\n\"Section 13. Sale, Lease, Transfer, Usufruct, etc. - The grantee shall not lease, transfer, grant the usufruct of, or sell this franchise or the rights and privileges acquired thereunder to any person, firm, company, corporation or other commercial or legal entity, nor merge with any other corporation or legal entity, nor shall the controlling interest of the grantee be transferred whether in whole or in part, and whether simultaneously or contemporaneously, to any such person, firm, company, corporation or entity without the prior approval of the Congress of the Philippines. Any person or entity to which this franchise is sold, transferred or assigned, shall be subject to the same conditions, terms, restrictions and limitations of this Act.\"\n\"Section 14. Equality Clause. - In the event that any competing individual, partnership or corporation shall receive a similar permit or franchise with terms and/or provisions more favorable that those herein granted or which tend to place the herein grantee at any disadvantage, such terms and/or provisions shall be deemed part hereof and shall be deemed part hereof and shall operate equally in favor of the herein grantee: Provided, That any terms and/or provisions herein granted which are not contained in other franchises that may hereafter be granted shall likewise be enjoyed by the future grantees: Provided, however, That the foregoing shall neither apply to nor affect the provisions concerning territory covered by the franchise and the life span of the franchise.\"\n\"Section 15. Reportorial Requirement. - The grantee shall submit an annual report of finances and operations to the Congress of the Philippines.\"\n\"Section 16. Applicability Clause. - The grantee shall comply with and be subject to the provisions of Commonwealth Act No. 146, as amended, otherwise known as the 'Public Services Act' and Republic Act No. 9136, otherwise known as the Electric Power Industry Reform Act of 2001'.\"\n\"Section 17. Repealability and Nonexclusivity Clause. - This franchise shall be subject to amendment, alteration or repeal by the Congress of the Philippines when the public interest so requires and shall not be interpreted as an exclusive grant of the privileges herein provided for.\"\n\"Section 18. Separability Clause. - If, for any reason, any of the sections or provisions of this Act is declared unconstitutional or invalid, the other parts or provisions hereof which are not affected thereby shall continue to be in full force and effect.\""}},{"id":"PH-H8427-A2","no":2,"noLabel":{"en":"Section 2."},"text":{"en":"Renewal/Extension of the Term of Franchise. - This franchise shall be for a term of twenty-five (25) years from the date of effectivity of this Act. This franchise shall be deemed ipso facto revoked in the event that the grantee fails to operate continuously for two (2) years."}},{"id":"PH-H8427-A3","no":3,"noLabel":{"en":"Section 3."},"text":{"en":"Acceptance and Compliance. - Acceptance of the amendment and extension/renewal of the franchise shall be given in writing within sixty (60) days from the date of effectivity of this Act."}},{"id":"PH-H8427-A4","no":4,"noLabel":{"en":"Section 4."},"text":{"en":"Repealing Clause. - All laws, decrees, orders, resolution, instructions and rules and regulations or parts thereof which are inconsistent with this Act are hereby deemed repealed or modified accordingly."}},{"id":"PH-H8427-A5","no":5,"noLabel":{"en":"Section 5."},"text":{"en":"Effectivity Clause. - This Act shall take effect fifteen (15) days after its publication in at least two (2) newspapers of general circulation."}}],"pack":"ph-p120"};
  FT["PH-H8428"] = {"id":"PH-H8428","coverage":"full","language":"en","sourceName":"LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation）","sourceUrl":"https://lawphil.net/statutes/repacts/ra2010/ra_9971_2010.html","fetchedAt":"2026-10-06","articleCount":4,"structureMode":"ARTICLE","title":{"zh":"设立Mati市","en":"An Act Establishing a National High School in Barangay Mayo, City of Mati, Province of Davao Oriental to Be Known as Mayo National High School and Appropriating Funds Therefor","orig":"An Act Establishing a National High School in Barangay Mayo, City of Mati, Province of Davao Oriental to Be Known as Mayo National High School and Appropriating Funds Therefor"},"level":"law","status":"active","topics":["administrative","education"],"docNumber":"Republic Act No. 9971","issuingBody":"Congress of the Philippines","promulgatedDate":"2010-02-10","completenessNote":"全文，共 4 条；逐字取自 LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation） 官方页面（statutes/repacts/ra2010/ra_9971_2010.html），未改写、未摘译、未节选；原文语言：英语。 条文抬头依源文为 “Section N.” 等形式，本库统一规范为 “Section N.”；首行抬头与条内标题的分段依源文块级边界还原。","country":"PH","countryName":"菲律宾","layer":"intl","articles":[{"id":"PH-H8428-A1","no":1,"noLabel":{"en":"Section 1."},"text":{"en":"Establishment of a National High School. - There is hereby established, under the supervision of the Department of Education, a national high school in Barangay Mayo, City of Mati, Province of Davao Oriental to be known as Mayo National High School."}},{"id":"PH-H8428-A2","no":2,"noLabel":{"en":"Section 2."},"text":{"en":"Appropriations. - The Secretary of Education shall immediately include in the Department's program the operationalization of Mayo National High School, the funding of which shall be included in the annual General Appropriations Act."}},{"id":"PH-H8428-A3","no":3,"noLabel":{"en":"Section 3."},"text":{"en":"Implementation. - The Secretary of Education shall issue such rules and regulations as may be necessary to carry out the purpose of this Act."}},{"id":"PH-H8428-A4","no":4,"noLabel":{"en":"Section 4."},"text":{"en":"Effectivity. - This Act shall take effect fifteen (15) days after its publication in the Official Gazette."}}],"pack":"ph-p120"};
