  FT["PH-H8470"] = {"id":"PH-H8470","coverage":"full","language":"en","sourceName":"LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation）","sourceUrl":"https://lawphil.net/statutes/repacts/ra2010/ra_10013_2010.html","fetchedAt":"2026-10-06","articleCount":3,"structureMode":"ARTICLE","title":{"zh":"设立Aguinaldo市","en":"An Act Converting the Ubao Taang Provincial Road in the Municipality of Aguinaldo, Province of Ifugao Into a National Road","orig":"An Act Converting the Ubao Taang Provincial Road in the Municipality of Aguinaldo, Province of Ifugao Into a National Road"},"level":"law","status":"active","topics":["general"],"docNumber":"Republic Act No. 10013","issuingBody":"Congress of the Philippines","promulgatedDate":"2010-02-23","completenessNote":"全文，共 3 条；逐字取自 LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation） 官方页面（statutes/repacts/ra2010/ra_10013_2010.html），未改写、未摘译、未节选；原文语言：英语。 条文抬头依源文为 “Section N.” 等形式，本库统一规范为 “Section N.”；首行抬头与条内标题的分段依源文块级边界还原。","country":"PH","countryName":"菲律宾","layer":"intl","articles":[{"id":"PH-H8470-A1","no":1,"noLabel":{"en":"Section 1."},"text":{"en":"The Ubao - Taang Provincial Road traversing barangays Ubao, Chalalo, Mongayang, Botac, Awayan, Damag, Jacmal and Taang, all in the Municipality of Aguinaldo, Province of Ifugao is hereby converted into a national road."}},{"id":"PH-H8470-A2","no":2,"noLabel":{"en":"Section 2."},"text":{"en":"The Secretary of the Department of Public Works and Highways shall issue the necessary rules, orders and circulars to implement the provision of this Act."}},{"id":"PH-H8470-A3","no":3,"noLabel":{"en":"Section 3."},"text":{"en":"This Act shall take effect fifteen (15) days after its publication in a newspaper of general circulation."}}],"pack":"ph-p120"};
